export function ProvisionalDdrByte0Routes() {
  return <>{provisionalByte0Routes.map(({ name, from, to, layer, points }) => {
    const first = points[0], last = points[points.length - 1]
    const path = points.map(([x, y]) => ({ x, y }))
    return <trace key={name} name={name} from={from} to={to} width={0.1} pcbPath={layer === "top"
      ? [from, ...path, to]
      : [from, { x:first[0], y:first[1], via:true, fromLayer:"top", toLayer:layer }, ...path,
        { x:last[0], y:last[1], via:true, fromLayer:layer, toLayer:"top" }, to]} />
  })}</>
}
